/**
 * Harvest abcjs's SELECTION oracle — `engraver.selectables`, the array a host clicks into.
 *
 * ── WHY IT IS RUN RATHER THAN COPIED ────────────────────────────────────────
 * `tests/visual/selection.test.js` holds 389 expected entries across four cases, and they
 * are the biggest unharvested oracle in abcjs's suite. They are NOT copied out of the file:
 * the four `doSelectionTest(abc, expected, options, audio)` calls are extracted by
 * EVALUATING it with `describe`/`it`/the helper replaced, and every expectation is then
 * generated by RUNNING abcjs 6.7.0 — the same distinction that caught abcjs's own suite
 * disagreeing with abcjs on `output-miss-accidental` during the transpose arc.
 *
 * It caught something here too, and the file's own claim is kept beside ours in
 * `testFileSays` rather than discarded:
 *
 *   - **`selection-clefs` rows 3 and 6.** A written `C` under `clef=tenor` and under
 *     `clef=bass` sounds MIDI 60 in abcjs 6.7.0; the test file expects 48 and 72. The four
 *     octave-marked clefs (`treble±8`, `bass±8`) agree with the file, so what the file
 *     asserts is a clef-octave transposition that 6.7.0 applies only to the `±8` forms.
 *   - **Nine `y` attributes on TEXT rows of `selection-multiple`**, and that one is OUR
 *     HARNESS rather than abcjs. `%%titlefont Times New Roman 22.0` renders at 29px, and
 *     `dump-svg.js`'s `fontHeights` — the calibrated WebKit table every golden in both
 *     corpora is generated with — has SEVEN entries and 29 is not one, so it falls through
 *     to `size + 2` = 31 where a browser measures 32.13. MEASURED, not reasoned: putting
 *     32.13 into the table reproduces the test file's 82.34 for the subtitle to the digit,
 *     while changing the 22px entry moves nothing. The fallback is deliberate and
 *     `GOLDEN_TEXT_HEIGHTS` reproduces it on purpose, so the oracle keeps the harness's
 *     number — but any tune setting a font size outside {15,16,17,19,20,21,27} has a page
 *     that a browser would draw differently, in every corpus here.
 *
 * ── WHAT IS NOT HARVESTED ───────────────────────────────────────────────────
 * `size` is `svgEl.getBBox()` on a GROUP — a browser ink measurement of glyph outlines.
 * jsdom implements it for nothing and `dump-svg.js` stubs it for `<text>`/`<tspan>` only,
 * so it cannot be produced here at all. The test file's numbers are carried in
 * `testFileSays` and the gate declares the axis rather than inventing it.
 *
 * ── LICENCE ─────────────────────────────────────────────────────────────────
 * The ABC text and the expectations are abcjs's authors' work, and abcjs is MIT.
 *
 *   node scripts/harvest-abcjs-selection.mjs
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const config = JSON.parse(readFileSync(join(root, 'abcts.config.json'), 'utf-8'))
const abcjsPath = join(root, config.abcjsRef)
const tools = join(root, config.goldens, '..')
const SOURCE = join(abcjsPath, 'tests/visual/selection.test.js')
const outDir = join(root, 'tests', 'corpus-selection')

const require = createRequire(join(tools, 'package.json'))
const { JSDOM } = require('jsdom')
const charWidths = require(join(tools, 'dump-elements-char-widths.js'))

// ── the four cases, out of the test file itself ─────────────────────────────
const text = readFileSync(SOURCE, 'utf-8')
const cases = []
let current = null
// The file declares `doSelectionTest` at top level, so cut it out and hand ours in.
const body = text.replace(/^function doSelectionTest[\s\S]*?\n}/m, '')
new Function('describe', 'it', 'doSelectionTest', 'chai', 'abcjs', 'copyAbcEl', 'copySvgEl', body)(
  (_name, fn) => fn(),
  (name, fn) => { current = name; fn() },
  (abc, expected, options, audio) =>
    cases.push({ slug: current, abc, options: options ?? {}, audio: audio === true, expected }),
  { assert: { deepStrictEqual: () => {} } },
  { renderAbc: () => [{ engraver: { selectables: [] } }] },
  (x) => x,
  (x) => x,
)

// ── abcjs, in jsdom, with the GOLDEN GENERATOR'S text metrics ───────────────
// Lifted from `dump-svg.js:50-131` so this oracle sees exactly what every other golden in
// both corpora was generated with. See the note above on its seven-entry height table.
const fontHeights = { 27: 29.91, 21: 23.27, 20: 22.16, 19: 21.06, 17: 18.84, 16: 18.52, 15: 17.5 }
const calcWidth = (str, fontSize, fontWeight) => {
  if (!str) return 0
  let fontType = 'repeatfont'
  if (fontSize >= 27) fontType = 'titlefont'
  else if (fontSize >= 21) fontType = 'subtitlefont'
  else if (fontSize >= 20) fontType = 'partsfont'
  else if (fontSize >= 19) fontType = 'measurefont'
  else if (fontSize >= 17) fontType = fontWeight === 'bold' ? 'vocalfont' : 'repeatfont'
  else if (fontSize >= 16) fontType = 'gchordfont'
  const widths = charWidths[fontType] ?? charWidths.repeatfont ?? {}
  let maxWidth = 0
  for (const line of str.split('\n')) {
    let lineWidth = 0
    for (const ch of line) lineWidth += widths[ch] ?? 8
    if (lineWidth > maxWidth) maxWidth = lineWidth
  }
  return maxWidth
}

const dom = new JSDOM('<!DOCTYPE html><html><body><div id="paper"></div></body></html>')
const origCreateElementNS = dom.window.document.createElementNS.bind(dom.window.document)
dom.window.document.createElementNS = (ns, tag) => {
  const el = origCreateElementNS(ns, tag)
  if (tag === 'text' || tag === 'tspan') {
    el.getBBox = () => {
      const fontSize = parseFloat(el.getAttribute('font-size')) || 16
      let fontWeight = el.getAttribute('font-weight') || 'normal'
      if (fontWeight === 'normal' && el.parentElement)
        fontWeight = el.parentElement.getAttribute('font-weight') || 'normal'
      let h = fontHeights[Math.round(fontSize)] ?? fontSize + 2
      let w = 0
      const tspans = el.querySelectorAll ? el.querySelectorAll('tspan') : []
      if (tspans.length > 0) {
        let nonEmpty = 0
        for (const tspan of tspans) {
          const ttext = tspan.textContent || ''
          if (ttext.length > 0) {
            w = Math.max(w, calcWidth(ttext, fontSize, fontWeight))
            nonEmpty += 1
          }
        }
        if (nonEmpty > 1) h = h + (nonEmpty - 1) * fontSize * 1.2
      } else {
        w = calcWidth(el.textContent || '', fontSize, fontWeight)
      }
      return { x: 0, y: 0, width: w, height: h }
    }
  }
  return el
}
global.document = dom.window.document
global.window = dom.window
const ABCJS = require(join(abcjsPath, 'index'))

// `copySvgEl` / `copyAbcEl`, verbatim from the test file's own helpers.
const INTERESTING = ['x', 'y', 'selectable', 'tabindex', 'data-index']
const copySvgEl = (svgEl) => {
  const el = {}
  for (const attr of svgEl.attributes)
    if (INTERESTING.includes(attr.nodeName)) el[attr.nodeName] = attr.nodeValue
  return el
}
const copyAbcEl = (abcEl) => {
  const el = {}
  for (const key of Object.keys(abcEl)) if (key !== 'abselem') el[key] = abcEl[key]
  return el
}

mkdirSync(outDir, { recursive: true })
const out = cases.map((c) => {
  dom.window.document.getElementById('paper').innerHTML = ''
  const visualObj = ABCJS.renderAbc('paper', c.abc, { ...c.options })
  if (c.audio) visualObj[0].setUpAudio()
  const rows = visualObj[0].engraver.selectables.map((sel) => ({
    draggable: sel.isDraggable,
    svgEl: copySvgEl(sel.svgEl),
    // JSON round-trip: the abcelem is a live parse element and carries back-references.
    abcEl: JSON.parse(JSON.stringify(copyAbcEl(sel.absEl.abcelem))),
  }))
  const testFileSays = c.expected.map((e, i) => {
    const ours = rows[i]
    const same =
      ours !== undefined &&
      JSON.stringify(sorted({ draggable: e.draggable, svgEl: e.svgEl, abcEl: e.abcEl })) ===
        JSON.stringify(sorted({ draggable: ours.draggable, svgEl: ours.svgEl, abcEl: ours.abcEl }))
    // `size` is a browser getBBox and is kept on EVERY row; the rest only where it differs.
    return same ? { size: e.size } : { size: e.size, draggable: e.draggable, svgEl: e.svgEl, abcEl: e.abcEl }
  })
  return { slug: c.slug, abc: c.abc, options: c.options, audio: c.audio, rows, testFileSays }
})

/** Deep key-sorted copy — `deepStrictEqual` does not care about key order and neither do we. */
function sorted(value) {
  if (Array.isArray(value)) return value.map(sorted)
  if (value === null || typeof value !== 'object') return value
  const out = {}
  for (const k of Object.keys(value).sort()) out[k] = sorted(value[k])
  return out
}

writeFileSync(join(outDir, 'golden.json'), `${JSON.stringify(out, null, 1)}\n`)
const disagreements = out.reduce(
  (n, c) => n + c.testFileSays.filter((t) => t.abcEl !== undefined).length,
  0,
)
console.log(
  `${out.length} cases, ${out.reduce((n, c) => n + c.rows.length, 0)} selectables written to tests/corpus-selection/golden.json` +
    ` — ${disagreements} rows where abcjs's own test file disagrees with abcjs`,
)
